 def test_manifest_baseline_382_and_exact_three_target_files(self):
  c=bound();old=load_prior('naver_report_progress_patch.py');old.bind_base(c.BASE)
  self.assertEqual(c.OLD_MANIFEST,old.OLD_MANIFEST);self.assertEqual(len(c.TARGET_MANIFEST),166)
  self.assertEqual({n for n in c.OLD_MANIFEST if c.OLD_MANIFEST[n]!=c.TARGET_MANIFEST[n]},TARGET_PATHS)
  self.assertEqual({n:c.TARGET_MANIFEST[n] for n in PATHS},{'naver_engine/setup_strategy_evidence.py': (420, 32012, '7a1b5cd328fa326f079a75e91e0a0e983ca13cd5bdd69b6c659ddee71116fdd8')})
  self.assertEqual(c.manifest_digest(c.OLD_MANIFEST),c.R1_M);self.assertEqual(c.OLD_MANIFEST['naver_engine/backup.py'],c.R1_D['naver_engine/backup.py'])
  self.assertEqual(c.REPORT_ASSETS,c.OLD_REPORT_ASSETS)
  self.assertEqual((c.OLD_COMMIT,c.ROLLBACK_COMMIT,c.BASE_PREPARE_RUN,c.BASE_APPLY_OPERATION),(R1,R1,'39373903231','98dc5ca60ef2a65f9c9399b8cad1f7d9'))
  self.assertEqual(c.STORE_SHA256['old'],c.STORE_SHA256['target']);self.assertEqual(c.OLD_SCHEMA,c.TARGET_SCHEMA)
